INSERT INTO blog_posts (slug,title_fr,title_en,excerpt_fr,excerpt_en,content_fr,category_id,is_published,is_featured,view_count,published_at) VALUES
('top-10-medinas-maroc','Top 10 des médinas à visiter au Maroc','Top 10 medinas to visit in Morocco',
'De Marrakech à Fès en passant par Chefchaouen, découvrez les médinas les plus fascinantes du Maroc.','From Marrakech to Fes via Chefchaouen, discover Morocco''s most fascinating medinas.',
'<p>Le Maroc possède certaines des médinas les plus authentiques et préservées du monde entier. Inscrites au patrimoine mondial de l''UNESCO pour la plupart, elles sont le reflet vivant d''une civilisation millénaire.</p><h2>1. La médina de Fès</h2><p>La plus grande médina médiévale du monde, avec ses 9 500 ruelles, ses tanneries légendaires et ses mosquées ancestrales.</p><h2>2. La médina de Marrakech</h2><p>Autour de la mythique place Jemaa El-Fna, un labyrinthe de souks thématiques où tous les sens s''éveillent.</p><h2>3. Chefchaouen</h2><p>La ville bleue du Rif, où chaque ruelle peinte en nuances d''azur est une invitation à la photographie.</p>',
(SELECT id FROM blog_categories WHERE slug='voyage'),TRUE,TRUE,1247,'2025-05-15'),

('guide-sahara-marocain','Guide complet : voyager dans le Sahara marocain','Complete guide: travelling in the Moroccan Sahara',
'Tout ce qu''il faut savoir pour préparer votre aventure dans le désert marocain : Merzouga, bivouac, chameau et étoiles.','Everything you need to know to prepare your Moroccan desert adventure.',
'<p>Le Sahara marocain est l''une des expériences les plus inoubliables qu''un voyageur puisse vivre. Voici notre guide complet pour préparer votre aventure.</p><h2>Quand partir ?</h2><p>La meilleure saison est d''octobre à avril, quand les températures sont douces (20-28°C le jour). L''été est déconseillé (40-50°C).</p><h2>Comment y aller ?</h2><p>Depuis Marrakech, comptez 8-9h de route via le col de Tichka et Ouarzazate. Les circuits organisés sont la meilleure option.</p>',
(SELECT id FROM blog_categories WHERE slug='conseils'),TRUE,FALSE,834,'2025-04-22'),

('experience-football-espagne','Football Experience : Bernabéu et Camp Nou en 7 jours','Football Experience: Bernabéu and Camp Nou in 7 days',
'Notre programme Football Experience Espagne vous emmène dans les temples du football mondial à Madrid et Barcelone.','Our Football Experience Spain program takes you to the world''s football temples.',
'<p>Pour tout fan de football, visiter le Bernabéu et le Camp Nou est un rêve absolu. Notre programme de 7 jours vous permet de vivre cette expérience de façon unique.</p><h2>Jour 1-3 : Madrid</h2><p>Tour officiel du stade Santiago Bernabéu, musée Real Madrid, et si possible assistance à un match. Visite du Prado et tapas en soirée.</p><h2>Jour 4-7 : Barcelone</h2><p>Camp Nou Experience, musée FC Barcelona, Barceloneta et architecture de Gaudí.</p>',
(SELECT id FROM blog_categories WHERE slug='voyage'),TRUE,TRUE,2156,'2025-06-01'),

('gastronomie-marocaine-secrets','Les secrets de la gastronomie marocaine','The secrets of Moroccan gastronomy',
'Tajine, couscous, pastilla, harira… plongez au cœur des saveurs et épices qui font la richesse de la cuisine marocaine.','Tagine, couscous, pastilla, harira... dive into the flavors and spices of Moroccan cuisine.',
'<p>La cuisine marocaine est l''une des plus riches et complexes du monde, fruit d''un brassage de cultures berbère, arabe, andalouse et africaine.</p><h2>Le tajine</h2><p>Cuit lentement dans son plat conique en terre cuite, le tajine développe des arômes incomparables.</p><h2>Le couscous du vendredi</h2><p>Plat traditionnel servi après la prière du vendredi, le couscous est bien plus qu''un repas, c''est un rituel familial.</p>',
(SELECT id FROM blog_categories WHERE slug='gastronomie'),TRUE,FALSE,567,'2025-05-28');

